import re, os, collections
root='AlgebraicJacobian'
def path_of(mod):
    return mod.replace('.', '/')+'.lean'
def imports(f):
    out=[]
    try:
        for line in open(f, encoding='utf-8'):
            m=re.match(r'^import\s+(\S+)', line)
            if m: out.append(m.group(1))
            elif line.strip() and not line.startswith('/-') and not line.startswith('--') and re.match(r'^(set_option|namespace|open|universe|/-!)', line):
                break
    except FileNotFoundError:
        pass
    return out
def closure(start):
    seen=set(); stack=[start]
    while stack:
        m=stack.pop()
        if m in seen: continue
        seen.add(m)
        p=path_of(m)
        if m.startswith('AlgebraicJacobian') and os.path.exists(p):
            stack.extend(imports(p))
    return seen
for target in ['AlgebraicJacobian.RiemannRoch.Degree','AlgebraicJacobian.RiemannRoch.RelPicDegree','AlgebraicJacobian.Picard.Pic0Functor','AlgebraicJacobian.RiemannRoch.ClassDegMapIso']:
    c=closure(target)
    aj=[m for m in c if m.startswith('AlgebraicJacobian')]
    bad=[]
    for m in aj:
        p=path_of(m)
        if os.path.exists(p):
            txt=open(p,encoding='utf-8').read()
            for i,l in enumerate(txt.split('\n'),1):
                s=l.strip()
                if s=='sorry' or s.endswith(':= sorry') or re.search(r'\bsorry\b', s) and not s.startswith('--') and 'sorry-free' not in s and '`sorry`' not in s:
                    bad.append((m,i,s[:80]))
    print(target, 'files:', len(aj), 'sorry hits:', bad)
EOF

